// 1. Get data from the node two steps back (referenced by its name)
const docData = $('ABDUL: GET PREVIOUS NODE DATA').all();

// Build a lookup map: user -> docLink
const docLinkMap = {};
for (const item of docData) {
  const user = item.json.user;
  const docLink = item.json.docLink;
  if (user) {
    docLinkMap[user] = docLink;
  }
}

// --- Manila time helper (Asia/Manila is UTC+8 year-round, no DST) ---
const MANILA_OFFSET_MS = 8 * 60 * 60 * 1000;

function toManila(field) {
  if (!field) return null;

  // Accepts either { dateTime, timeZone } or a plain ISO string
  const raw = typeof field === 'string' ? field : field.dateTime;
  if (!raw) return null;

  // Graph sends 7 fractional digits; JS Date only reliably parses 3
  let s = String(raw).trim().replace(/(\.\d{3})\d+/, '$1');

  // If the string carries no zone designator, apply the one Graph reported (UTC)
  const hasZone = /(Z|[+-]\d{2}:?\d{2})$/.test(s);
  if (!hasZone) {
    const tz = (typeof field === 'object' && field.timeZone) || 'UTC';
    s += tz.toUpperCase() === 'UTC' ? 'Z' : 'Z'; // non-UTC source zones fall back to UTC
  }

  const utc = new Date(s);
  if (isNaN(utc.getTime())) return null;

  const m = new Date(utc.getTime() + MANILA_OFFSET_MS);
  const pad = n => String(n).padStart(2, '0');

  const date = `${m.getUTCFullYear()}-${pad(m.getUTCMonth() + 1)}-${pad(m.getUTCDate())}`;
  const time = `${pad(m.getUTCHours())}:${pad(m.getUTCMinutes())}`;

  return {
    iso: `${date}T${time}:${pad(m.getUTCSeconds())}+08:00`,
    date,          // e.g. "2026-08-13"
    time,          // e.g. "00:00"
    timeZone: 'Asia/Manila'
  };
}

// 2. Get data from the immediately previous node (this node's input)
const items = $input.all();

// 3. Build the trimmed output with docLink merged into metadata
const results = items.map(item => {
  const d = item.json;
  const userName = d.metadata?.user_name;

  return {
    json: {
      importance: d.importance,
      status: d.status,
      title: d.title,
      createdDateTime: d.createdDateTime,
      lastModifiedDateTime: d.lastModifiedDateTime,
      dueDateTime: toManila(d.dueDateTime),             // null when absent
      completedDateTime: toManila(d.completedDateTime), // null when absent
      hasAttachments: d.hasAttachments,
      body: {
        content: d.body?.content,
        contentType: d.body?.contentType
      },
      metadata: {
        display_name: d.metadata?.display_name,
        user_name: userName,
        docLink: docLinkMap[userName] || null
      }
    }
  };
});

return results;

