      importance: d.importance,
      status: d.status,
      title: d.title,
      createdDateTime: d.createdDateTime,
      lastModifiedDateTime: d.lastModifiedDateTime,
      dueDateTime: toManila(d.dueDateTime),             // null when absent
      completedDateTime: toManila(d.completedDateTime), // null when absent
      hasAttachments: d.hasAttachments,
      body: {
        content: d.body?.content,
        contentType: d.body?.contentType
      },
      metadata: {
