const items = $input.all();

return items.map(item => {
  const raw = item.json.output || '';

  // Strip markdown bold markers (**text**)
  let text = raw.replace(/\*\*/g, '');

  // Normalize line endings and trim outer whitespace
  text = text.replace(/\r\n/g, '\n').trim();

  // Try to split into Summary / Details sections
  const summaryMatch = text.match(/Summary:\s*([\s\S]*?)\n\s*\n?Details:/i);
  const detailsMatch = text.match(/Details:\s*([\s\S]*)/i);

  const summary = summaryMatch
    ? summaryMatch[1].replace(/\n+/g, ' ').replace(/\s{2,}/g, ' ').trim()
    : text.replace(/\n+/g, ' ').replace(/\s{2,}/g, ' ').trim();

  let details = [];
  if (detailsMatch) {
    details = detailsMatch[1]
      .split('\n')
      .map(line => line.replace(/^-+\s*/, '').trim())
      .filter(line => line.length > 0);
  }

  // Fully flattened, single-line readable version
  const cleanedText = text.replace(/\n+/g, ' ').replace(/\s{2,}/g, ' ').trim();

  return {
    json: {
      summary,
      details,
      cleanedText
    }
  };
});

