      const [y, m, d] = dateValue.date.split('-').map(Number);
      if (y && m && d) {
        const localDate = new Date(y, m - 1, d);
        return localDate.toLocaleDateString('en-US', { month: 'long', day: 'numeric', year: 'numeric' });
      }
    }
    if (dateValue.iso) {
      const d = new Date(dateValue.iso);
      if (!isNaN(d.getTime())) {
        return d.toLocaleDateString('en-US', { month: 'long', day: 'numeric', year: 'numeric' });
      }
    }
    return 'No due date';
  }

  const d = new Date(dateValue);
  if (isNaN(d.getTime())) return 'No due date';
  return d.toLocaleDateString('en-US', { month: 'long', day: 'numeric', year: 'numeric' });
}

// True only when the value actually carries a date (handles both plain
// strings and the {iso, date, time, timeZone} object shape, and `null`).
function hasDateValue(dateValue) {
  if (!dateValue) return false;
  if (typeof dateValue === 'object') return Boolean(dateValue.iso || dateValue.date);
  return true;
}

function capitalize(str) {
  if (!str) return '';
  return str.charAt(0).toUpperCase() + str.slice(1);
}

function statusLabel(status) {
  const map = {
    notStarted: 'Not Started',
    inProgress: 'In Progress',
    completed: 'Completed',
    waitingOnOthers: 'Waiting on Others',
    deferred: 'Deferred',
  };
  return map[status] || capitalize(status || 'Unknown');
}

function extractDocumentId(docLink) {
  if (!docLink) return null;
  const match = docLink.match(/\/document\/d\/([a-zA-Z0-9_-]+)/);
  return match ? match[1] : null;
}

// Google Docs normalizes \r\n and stray \r to \n on insert, silently
// dropping the \r characters. If we don't do the same here first, our
// JS-computed character offsets for later formatting requests drift out
// of sync with the real document, causing "Index X must be less than the
// end index" errors. Normalize everything up front so counts always match.
function sanitizeText(str) {
  if (!str) return '';
  return String(str).replace(/\r\n/g, '\n').replace(/\r/g, '\n');
}

// ---- Document builder --------------------------------------------------
// Walks through "blocks" (heading / paragraph / bullets / spacer) and
// produces the concatenated text plus the formatting requests.

function buildDocRequests(task, insertIndex, isAppending) {
  let fullText = '';
  let cursor = insertIndex;
  const styleRequests = [];

  // When appending after existing content, add a couple of blank lines
  // first so the new entry doesn't run straight into the previous one.
  if (isAppending) {
    fullText += '\n\n';
    cursor += 2;
  }

  function addHeading(level, text) {
    const start = cursor;
    fullText += text + '\n';
    const end = cursor + text.length + 1; // include trailing newline
    styleRequests.push({
      updateParagraphStyle: {
        range: { startIndex: start, endIndex: end },
        paragraphStyle: { namedStyleType: `HEADING_${level}` },
        fields: 'namedStyleType',
      },
    });
    cursor = end;
  }

  function addParagraph(runs) {
    // runs = [{ text: '...', bold: true|false }, ...]
    runs.forEach((run) => {
      const runStart = cursor;
      fullText += run.text;
      cursor += run.text.length;
      if (run.bold && run.text.length > 0) {
        styleRequests.push({
          updateTextStyle: {
            range: { startIndex: runStart, endIndex: cursor },
            textStyle: { bold: true },
            fields: 'bold',
          },
        });
      }
    });
    fullText += '\n';
    cursor += 1;
  }

  function addBullets(items) {
    if (!items || !items.length) return;
    const start = cursor;
    items.forEach((item) => {
      fullText += item + '\n';
      cursor += item.length + 1;
    });
    styleRequests.push({
      createParagraphBullets: {
        range: { startIndex: start, endIndex: cursor },
        bulletPreset: 'BULLET_DISC_CIRCLE_SQUARE',
      },
    });
  }

  const label = (text) => ({ text, bold: true });
  const value = (text) => ({ text: `${text}\n`.slice(0, -1), bold: false }); // plain text

  const title = sanitizeText(task.title) || 'Untitled Task';
  const status = statusLabel(task.status);
  const importance = capitalize(task.importance || 'normal');
  const userName = sanitizeText(task.metadata?.user_name) || 'Unknown';
  const listName = sanitizeText(task.metadata?.display_name) || 'Unknown List';
  const dueDate = formatDate(task.dueDateTime);
  const createdDate = formatDate(task.createdDateTime);
  const modifiedDate = formatDate(task.lastModifiedDateTime);

  // Completed is driven by `status`, not just whether completedDateTime is
  // populated. Some To Do clients leave a stale completedDateTime behind
  // after a task is reopened (status back to notStarted/inProgress/etc),
  // so trusting the field alone would show a completed date on a task
  // that's actually active again. If status says completed but no
  // timestamp came through, we still say "Yes" rather than silently
  // falling back to "Not Completed".
  const completedDate =
    task.status === 'completed'
      ? (hasDateValue(task.completedDateTime) ? formatDate(task.completedDateTime) : 'Yes')
      : 'Not Completed';

  const originalNotes = sanitizeText(task.body?.content).trim() || '(none)';
  const summary = sanitizeText(task.ai_generated_data?.summary) || '(none)';
  const details = (task.ai_generated_data?.details || []).map(sanitizeText);

  // Title
  addHeading(1, 'AI-Generated Task Notes');

  // Task Overview
  addHeading(2, 'Task Overview');
  addParagraph([label('Task: '), value(title)]);
  addParagraph([label('Status: '), value(status)]);
  addParagraph([label('Importance: '), value(importance)]);
  addParagraph([label('User: '), value(userName)]);
  addParagraph([label('Task List Name: '), value(listName)]);
  addParagraph([label('Due Date: '), value(dueDate)]);
  addParagraph([label('Completed: '), value(completedDate)]);
  addParagraph([label('Created: '), value(createdDate)]);
  addParagraph([label('Last Modified: '), value(modifiedDate)]);

  // Original notes
  addHeading(2, 'Original notes');
  addParagraph([{ text: originalNotes, bold: false }]);

  // AI Summary
  addHeading(2, 'AI Summary');
  addParagraph([{ text: summary, bold: false }]);

  // Details
  addHeading(2, 'Details');
  addBullets(details.length ? details : ['(none)']);


  const requests = [
    {
      insertText: {
        location: { index: insertIndex },
        text: fullText,
      },
    },
    ...styleRequests,
  ];

  return { text: fullText, requests };
}

// ---- Main ---------------------------------------------------------------
// `items` here = output of the "Get Document" HTTP node (one documents.get
// response per task). We pair each with its original task data from the
// earlier "FINALIZE OUTPUT" node by index.

const output = items.map((item, index) => {
  const task = $('RICH: FINALIZE OUTPUT').all()[index].json; // original task + documentId
  const docResponse = item.json; // documents.get response

  // Prefer documentId straight from the docLink on the task itself — this
  // is always present in the raw task data, unlike the Get Document
  // response (which may have documentId stripped out if a `fields` query
  // param filters it) or the earlier node (if it didn't pass it through).
  const documentId =
    extractDocumentId(task.metadata?.docLink) ||
    docResponse.documentId ||
    task.documentId;

  const content = docResponse.body?.content || [];
  const lastElement = content[content.length - 1];
  // The final structural element's endIndex is one past the doc's last
  // character (there's always a trailing newline you can't write over),
  // so we insert one position before it.
  const rawEndIndex = lastElement?.endIndex || 1;
  const insertIndex = Math.max(rawEndIndex - 1, 1);
  const isAppending = insertIndex > 1; // false only for a brand-new empty doc

  const { text, requests } = buildDocRequests(task, insertIndex, isAppending);

  return {
    json: {
      documentId,
      text,
      requestBody: { requests },
    },
  };
});

return output;
